def truth_class(text):
    s=' '+text.lower().strip()+' '
    if 'no recurrence' in s or 'no recurrence' in s.replace('  ',' '):
        return 1
    if re.search(r'\b(cr|pr|sd)\b', s):
        return 1
    if 'recurrence' in s or 'progression' in s or re.search(r'\bpd\b', s):
        return 0
    return None
patient_truth={}
for i,r in enumerate(s4_rows, start=1):
    if not r or not re.match(r'GC-\d+', str(r[0]).strip()):
        continue
    pid=str(r[0]).strip()
