    if len(r) > 2 and str(r[2]).strip().lower() == 'no':
        continue
    month_pos=None
    for j in range(5,len(r)):
        if re.fullmatch(r'\d+(?:\.\d+)?', str(r[j]).strip()):
            month_pos=j
